 if(w.realm===1){glow(730,130,160,'#ffcda690');circ(730,120,51,'#ffe1a9');for(let i=0;i<5;i++){let xx=i*270-w.cam.x*.14%270;ctx.beginPath();ctx.ellipse(xx+80,402,160,36,0,0,T);ctx.fillStyle='#6544794b';ctx.fill()}fill(0,H*.73,W,25,'#75d9f877');for(let i=0;i<6;i++)stroke(0,H*.74+i*21,W,H*.74+i*20,'#fff6',1)}
 else if(w.realm===2||w.realm===4){for(let i=0;i<9;i++){let y=25+i*65+Math.sin(w.time+i)*8;stroke(0,y,W,y+24,'#7affeb0b',20)}for(let i=0;i<25;i++){let x=(i*91+w.time*9)%W,y=(i*67+w.time*22)%H;circ(x,y,2+i%3,'#bfffff35')}glow(700,40,210,'#55e7fa33')}
 else if(w.realm===3){circ(760,91,59,'#dfefff');glow(760,91,120,'#baceff4c');for(let i=0;i<10;i++)stroke(i*115-w.cam.x*.09,80,i*115+60-w.cam.x*.09,0,'#b3bcff44',1)}
 else{circ(790,78,39,'#eee8ff');glow(790,78,95,'#c8aeff55');for(let i=0;i<15;i++){let x=(i*88-w.cam.x*.1+1400)%1200,y=42+i%6*38;diamond(x,y,2.2,'#d4c8ff77')}}
 if(w.realm===0||w.realm===4){for(let i=0;i<9;i++){const base=80+i*160-w.cam.x*.12;fill(base,120,74,245,'#080b2e77',6);fill(base+9,158,55,90,'#3ddfee23',28);stroke(base+30,158,base+30,246,'#efa6ff30',2);fill(base-8,112,88,13,'#21143e91',5)}}
