function drawGuard(w){if(w.invocationUntil<=w.time||g.selected==='jonathas')return;let p=w.p,remain=Math.ceil(w.invocationUntil-w.time);let c=CHARS[1],x=p.x+(p.face>0?76:-76),y=p.y;glow(x,y-25,95,'#2dfcff64');drawAvatar(x,y,c,1.33,w.time,w.mode,true);text(remain+'s',x,y-94,18,'#d4ffff');ctx.save();ctx.strokeStyle='#85fffaa8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y-10,53+Math.sin(w.time*5)*3,0,T);ctx.stroke();ctx.restore()}
