 bg(w);let realmArt=REALM_IMG[w.meta.id];if(realmArt?.complete&&realmArt.naturalWidth){ctx.save();ctx.globalAlpha=.17;ctx.filter=`hue-rotate(${w.stage*16}deg) saturate(1.4)`;ctx.drawImage(realmArt,0,0,W,H);ctx.filter='none';ctx.restore()}ctx.save();if(w.shakes>0){ctx.translate((Math.random()-.5)*w.shakes,(Math.random()-.5)*w.shakes)}ctx.translate(-w.cam.x,-w.cam.y);environment(w);
 for(let i=0;i<w.crystals.length;i++)drawGem(w,w.crystals[i],i);
